
#[cfg(test)]mod greater75_session_development_tests {
 use super::*;
 fn snapshot()->Snapshot{let mut s=super::super::native_login::LoginController::default().snapshot().clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();s.world.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}s.phase=LoginPhase::BattlePending;s.game_connected=true;s.selected_source=Some("isolated".into());s.selected_character=Some("fixture".into());s.inventory.owner=Some(native_inventory::Owner{connection:7,selection:1,character:"fixture".into()});let id=s.world.own_actor().unwrap().id;s.world.actors.get_mut(&id).unwrap().dead=true;s.world.hp=Some([0,100]);s.world.mp=Some([0,100]);s.world.learned_skills.clear();s}
 #[test]fn greater_ask_requires_exact_empty_NUL_while_normal_ask_stays_three_bytes(){assert_eq!(parse(&[36,66,1,0]).unwrap(),Some(322));assert_eq!(parse(&[36,65,1]).unwrap(),Some(321));for b in [&[36,66,1][..],&[36,66,1,0,0][..],&[36,66,1,b'x',0][..],&[36,65,1,0][..]]{assert!(parse(b).is_err());}}
 #[test]fn each_answer_echoes_its_question_once_without_spending_or_reviving(){let s=snapshot();let before=serde_json::to_value(&s.world).unwrap();for id in [321u16,322]{for yes in [false,true]{let mut q=Session::default();let mut ask=vec![36];ask.extend(id.to_le_bytes());if id==322{ask.push(0);}q.receive(&s,7,&ask).unwrap();let t=q.current(&s,7).unwrap().token();let mut expected=vec![35];expected.extend(id.to_le_bytes());expected.extend([u8::from(yes),0]);assert_eq!(q.answer(&s,7,&t,yes).unwrap(),Some(expected));assert!(q.answer(&s,7,&t,true).is_err());assert_eq!(serde_json::to_value(&s.world).unwrap(),before);}}}
 #[test]fn replacing_normal_and_greater_revokes_both_token_and_queued_command_id(){let s=snapshot();let mut q=Session::default();q.receive(&s,7,&[36,65,1]).unwrap();let old=q.current(&s,7).unwrap().token();q.receive(&s,7,&[36,66,1,0]).unwrap();let new=q.current(&s,7).unwrap().token();assert_ne!(old.command_id(true),new.command_id(true));assert!(q.answer(&s,7,&old,true).is_err());assert!(q.answer(&s,7,&new,true).unwrap().is_some());q.receive(&s,7,&[36,65,1]).unwrap();assert!(q.answer(&s,7,&new,true).is_err());}
 #[test]fn recipient_needs_dead_owner_but_no_learned_spell_or_MP(){let s=snapshot();let mut q=Session::default();assert!(q.receive(&s,7,&[36,66,1,0]).unwrap());assert_eq!(q.current(&s,7).unwrap().question_id(),322);for n in 0..4{let mut s=s.clone();let id=s.world.own_actor().unwrap().id;match n{0=>s.world.actors.get_mut(&id).unwrap().dead=false,1=>s.world.hp=Some([1,100]),2=>s.observer=true,_=>s.inventory.owner=None};let mut q=Session::default();q.receive(&s,7,&[36,66,1,0]).unwrap();assert!(q.current(&s,7).is_none());}}
 #[test]fn owner_and_dead_life_boundaries_reject_before_serializing322(){let s=snapshot();let mut q=Session::default();q.receive(&s,7,&[36,66,1,0]).unwrap();let t=q.current(&s,7).unwrap().token();assert!(q.answer(&s,8,&t,true).is_err());for n in 0..6{let mut s=s.clone();let id=s.world.own_actor().unwrap().id;match n{0=>s.world.generation+=1,1=>s.selected_source=Some("other".into()),2=>s.inventory.owner.as_mut().unwrap().selection+=1,3=>s.world.actors.get_mut(&id).unwrap().incarnation+=1,4=>s.world.actors.get_mut(&id).unwrap().action_sequence+=1,_=>s.game_connected=false};assert!(q.answer(&s,7,&t,true).is_err());}}
 #[test]fn accepted_wait_cannot_resend_and_local_abandonment_or_other_ask_retires(){let s=snapshot();let mut q=Session::default();q.receive(&s,7,&[36,66,1,0]).unwrap();let t=q.current(&s,7).unwrap().token();q.answer(&s,7,&t,true).unwrap();assert!(q.answer(&s,7,&t,true).is_err());assert!(q.answer(&s,7,&t,false).unwrap().is_none());assert!(q.current(&s,7).is_none());q.receive(&s,7,&[36,66,1,0]).unwrap();let t=q.current(&s,7).unwrap().token();assert!(!q.receive(&s,7,&[36,67,1,0]).unwrap());assert!(q.answer(&s,7,&t,true).is_err());}
}
